explanation:
This complete Swift example returns both the found position and a work count.

```swift
struct LookupResult {
    let index: Int?
    let comparisons: Int
}

func locate(_ target: Int, in values: [Int]) -> LookupResult {
    var comparisons = 0
    for (index, value) in values.enumerated() {
        comparisons += 1
        if value == target {
            return LookupResult(index: index, comparisons: comparisons)
        }
    }
    return LookupResult(index: nil, comparisons: comparisons)
}

let values = [4, 8, 12, 16]
let found = locate(12, in: values)
let missing = locate(20, in: values)
print(found.index ?? -1)
print(found.comparisons)
print(missing.index == nil)
print(missing.comparisons)
```

The outputs are 2, 3, true, and 4. The target 12 sits at index 2, after three comparisons. The missing target requires checking all four entries.

This second complete Swift program uses executable assertions to test a small search under consistent conditions.

```swift
struct Result {
    let index: Int?
    let comparisons: Int
}
func search(_ target: Int, in values: [Int]) -> Result {
    var count = 0
    for (index, value) in values.enumerated() {
        count += 1
        if value == target {
            return Result(index: index, comparisons: count)
        }
    }
    return Result(index: nil, comparisons: count)
}

let short = Array(0..<6)
let long = Array(0..<12)
let first = search(0, in: short)
let smallLast = search(5, in: short)
let largeLast = search(11, in: long)
let absent = search(-1, in: short)
assert(first.index == 0 && first.comparisons == 1)
assert(smallLast.index == 5 && smallLast.comparisons == 6)
assert(largeLast.comparisons == smallLast.comparisons * 2)
assert(absent.index == nil && absent.comparisons == short.count)
print("The small search checks passed")
```

assert reports failure in an assertion-enabled build if its condition is false; it is a development check, not user-facing input validation. Both growth runs search the last item, so they compare equivalent worst-case conditions.

