enum MinuteError: Error { case negative }
final class Trace { var events: [String] = [] }
func checkedMinutes(_ value: Int, trace: Trace) throws -> Int {
    trace.events.append("started")
    defer { trace.events.append("finished") }
    if value < 0 { throw MinuteError.negative }
    return value
